import { GEO } from './miami-geodata.js';
import { pointInPolygon } from './polygon.js';

// Downtown Miami & Brickell spatial configuration at true 1:1 scale, derived from the real geography in
// js/miami-geodata.js (generated by tools/build-miami.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), origin at the centreline crossing of Flagler St &
// Miami Ave, where Miami's street numbering starts; the grid runs true north-south. The detailed area runs from the
// Omni / Venetian Causeway in the north to Brickell's southern end, and from I-95 east to Biscayne Bay.
//
// This module keeps the export names the engine was written against (the New York original's), so the renderer,
// traffic, pedestrians, buildings and maps work unchanged; the Manhattan-only ones (avenues, Central Park, the East
// River bridges, the boroughs) are empty.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const DETAIL = GEO.frame.detail;
const CITY_NAME = 'Miami';

// ---------------------------------------------------------------------------------------------------------------------
// Land & water: the 4 m land mask (coastline flood fill minus the Miami River) and the bridge decks over the water
// ---------------------------------------------------------------------------------------------------------------------
const LM = GEO.landMask;
const LAND = new Uint8Array(LM.w * LM.h);
{
  let v = LM.first, k = 0;
  for (const n of LM.runs) {
    if (v) LAND.fill(1, k, k + n);
    k += n;
    v = v ? 0 : 1;
  }
}
function isLandAt(x, z) {
  const i = Math.floor((x - LM.x0) / LM.res);
  const j = Math.floor((z - LM.z0) / LM.res);
  if (i < 0 || j < 0 || i >= LM.w || j >= LM.h) return false;
  return LAND[j * LM.w + i] === 1;
}
const LAND_POLYGONS = GEO.land.map(toPts);
const MANHATTAN_COASTLINE = LAND_POLYGONS[0]; // the largest land mass (kept under its original export name)

// Road graph links that cross water: the bridges & causeway spans, as segments with their half width
const RG = GEO.roadGraph;
const RG_POS = [];
for (let i = 0; i < RG.nodes.length; i += 2) RG_POS.push({ x: RG.nodes[i], z: RG.nodes[i + 1] });
const BRIDGE_SPANS = [];
for (const [a, b, ni, w, , , inner] of RG.links) {
  const pts = [RG_POS[a], ...toPts(inner), RG_POS[b]];
  for (let k = 0; k + 1 < pts.length; k++) {
    const p = pts[k], q = pts[k + 1];
    const L = Math.hypot(q.x - p.x, q.z - p.z);
    let wet = 0, n = 0;
    for (let s = 0; s <= L; s += 4, n++) if (!isLandAt(p.x + ((q.x - p.x) * s) / L, p.z + ((q.z - p.z) * s) / L)) wet++;
    if (n && wet > 0) BRIDGE_SPANS.push({ ax: p.x, az: p.z, bx: q.x, bz: q.z, half: Math.max(3.5, w / 2), name: RG.names[ni], wet: wet / n });
  }
}
const SPAN_CELL = 64;
const SPAN_GRID = new Map();
for (const s of BRIDGE_SPANS) {
  const r = s.half + 2;
  for (let ix = Math.floor((Math.min(s.ax, s.bx) - r) / SPAN_CELL); ix <= Math.floor((Math.max(s.ax, s.bx) + r) / SPAN_CELL); ix++) {
    for (let iz = Math.floor((Math.min(s.az, s.bz) - r) / SPAN_CELL); iz <= Math.floor((Math.max(s.az, s.bz) + r) / SPAN_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!SPAN_GRID.has(k)) SPAN_GRID.set(k, []);
      SPAN_GRID.get(k).push(s);
    }
  }
}
function onBridgeDeck(x, z, pad = 0) {
  for (const s of SPAN_GRID.get(Math.floor(x / SPAN_CELL) * 100000 + Math.floor(z / SPAN_CELL)) || []) {
    const dx = s.bx - s.ax, dz = s.bz - s.az;
    const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / (dx * dx + dz * dz || 1e-9)));
    if (Math.hypot(s.ax + dx * t - x, s.az + dz * t - z) <= s.half + pad) return true;
  }
  return false;
}
/** Open water at (x, z): neither land nor a bridge deck */
function isWaterAt(x, z) {
  return !isLandAt(x, z) && !onBridgeDeck(x, z);
}

// ---------------------------------------------------------------------------------------------------------------------
// Bounds of the detailed area. Miami has no single shoreline to clamp against (the river and the bay cut through it),
// so the island bounds are the detailed box and the water test above keeps people & cars out of the water.
// ---------------------------------------------------------------------------------------------------------------------
const ISLAND_BOUNDS = { minX: DETAIL.minX, maxX: DETAIL.maxX, minZ: DETAIL.minZ, maxZ: DETAIL.maxZ, sidewalkHeight: 0.22, waterLevel: -1.6 };
function getIslandBoundsAtZ() {
  return { westX: DETAIL.minX - 400, eastX: DETAIL.maxX + 400 };
}
const CUT_Z = DETAIL.minZ;
// Nothing in Miami is inside these (the engine's Central Park special cases stay off)
const CENTRAL_PARK_BOUNDS = { minX: 1e7, maxX: 1e7 + 1, minZ: 1e7, maxZ: 1e7 + 1 };

// The Manhattan grid tables (avenues, numbered streets, Broadway, piers, bridges, boroughs): empty in Miami. The road
// network then builds every road from the street centreline graph (js/road-network.js, 4b).
const ALL_AVENUES = [];
const ALL_STREETS = [];
const AVENUES = [];
const STREETS = [];
const BROADWAY_LINE = [];
const getBroadwayX = () => 1e7;
const WATERFRONT_PIERS = [];
const EAST_RIVER_BRIDGES = [];
const OUTER_BRIDGES = [];
const streetZ = () => 1e7;
const avenueX = () => 1e7;
const NONE = [];
const ROOSEVELT_ISLAND_POLYGON = NONE, GOVERNORS_ISLAND_POLYGON = NONE, NJ_SHORELINE_POLYGON = NONE, WESTCHESTER_POLYGON = NONE,
  NASSAU_POLYGON = NONE, UPPER_MANHATTAN_POLYGON = NONE, BRONX_POLYGON = NONE, STATEN_ISLAND_POLYGON = NONE,
  RANDALLS_ISLAND_POLYGON = NONE, LIBERTY_ISLAND_POLYGON = NONE, ELLIS_ISLAND_POLYGON = NONE, MILL_ROCK_POLYGON = NONE;
// Miami Beach across Biscayne Bay (its bay shore to the Atlantic, South Pointe to ~41st St), from its coordinates: the far
// shore the water reflects at night and the maps draw (kept under the New York far shore's export name)
const MIAMI_BEACH_POLYGON = (() => {
  const x = (lon) => (lon - GEO.frame.lon) * 100250, z = (lat) => -(lat - GEO.frame.lat) * 110800;
  return [{ x: x(-80.1430), z: z(25.8600) }, { x: x(-80.1260), z: z(25.8600) }, { x: x(-80.1260), z: z(25.7680) }, { x: x(-80.1430), z: z(25.7680) }];
})();
const LONG_ISLAND_POLYGONS = [MIAMI_BEACH_POLYGON], BROOKLYN_POLYGONS = [], QUEENS_POLYGONS = [], BRONX_POLYGONS = [];
const LIBERTY_STATUE_POS = { x: 1e7, z: 1e7 };

// ---------------------------------------------------------------------------------------------------------------------
// Named roads (OSM ways) — maps, labels & lookups. Miami's quadrant names shortened the way street signs write them.
// ---------------------------------------------------------------------------------------------------------------------
function prettyName(n) {
  return n
    .replace(/\b(North|South)(east|west)\b/g, (_, a, b) => `${a[0]}${b[0].toUpperCase()}`)
    .replace(/\bNorth\b(?= \d)/g, 'N').replace(/\bSouth\b(?= \d)/g, 'S').replace(/\bEast\b(?= \d)/g, 'E').replace(/\bWest\b(?= \d)/g, 'W')
    .replace(/\bAvenue\b/g, 'Ave').replace(/\bStreet\b/g, 'St').replace(/\bBoulevard\b/g, 'Blvd').replace(/\bDrive\b/g, 'Dr')
    .replace(/\bRoad\b/g, 'Rd').replace(/\bTerrace\b/g, 'Ter').replace(/\bCourt\b/g, 'Ct').replace(/\bPlace\b/g, 'Pl')
    .replace(/\bCauseway\b/g, 'Cswy').replace(/\bLane\b/g, 'Ln');
}
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name: prettyName(name), raw: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist, horizontal }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every curb island (raised sidewalk slab) with its lot rectangles inside the property line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots, park: share covered by parkland,
//   parkName, rect: the island is an axis-aligned rectangle, frames: irregular islands' lots laid out along the
//   streets they front, [[θ, px, pz, rects], ...] (world = p + R_y(θ)·(local − p)), or null
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: Math.min(maxX - minX, maxZ - minZ) < 9
  };
});
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPolygon(b.poly, x, z)) return b;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
const RIVER_Z = (x) => 330 + Math.max(0, -x) * 0.08; // the Miami River's line across the grid (only for labels)
function districtAt(x, z) {
  if (z > RIVER_Z(x)) {
    if (x > 700 && z < 1200) return 'brickell_key';
    return 'brickell';
  }
  if (z < -1150) return x > 300 ? 'edgewater' : 'park_west';
  if (z < -600) return x > 350 ? 'museum_park' : 'arts_entertainment';
  return x > 420 ? 'bayfront' : 'downtown';
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);
const DISTRICT_NAMES = {
  brickell: 'Brickell', brickell_key: 'Brickell Key', edgewater: 'Edgewater', park_west: 'Park West', museum_park: 'Museum Park',
  arts_entertainment: 'Arts & Entertainment District', bayfront: 'Bayfront', downtown: 'Downtown Miami'
};

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks & teleports. Positions come from OSM footprints when the name is mapped, else from fixed coordinates.
// ---------------------------------------------------------------------------------------------------------------------
const site = (names, fallback) => {
  for (const n of [].concat(names)) if (LANDMARK_SITES[n]) return LANDMARK_SITES[n];
  return fallback;
};
const MIAMI_LANDMARKS = [
  ['freedom', 'Freedom Tower', 'Freedom Tower', ['Freedom Tower'], { x: 620, z: -1010 }],
  ['arena', 'Kaseya Center', 'Kaseya Center', ['Kaseya Center', 'FTX Arena', 'American Airlines Arena'], { x: 780, z: -1150 }],
  ['bayside', 'Bayside Marketplace', 'Bayside', ['Bayside Marketplace'], { x: 760, z: -480 }],
  ['bayfront', 'Bayfront Park', 'Bayfront Park', ['Bayfront Park'], { x: 760, z: -100 }],
  ['pamm', 'Pérez Art Museum Miami', 'PAMM', ['Pérez Art Museum Miami'], { x: 760, z: -1700 }],
  ['miamitower', 'Miami Tower', 'Miami Tower', ['Miami Tower', 'Bank of America Tower'], { x: 330, z: 80 }],
  ['sefc', 'Southeast Financial Center', 'SE Financial Ctr', ['Southeast Financial Center', 'Wells Fargo Center'], { x: 470, z: 150 }],
  ['cityctr', 'Brickell City Centre', 'Brickell City Ctr', ['Brickell City Centre'], { x: -100, z: 1000 }],
  ['brickellkey', 'Brickell Key', 'Brickell Key', ['Brickell Key'], { x: 900, z: 650 }],
  ['panorama', 'Panorama Tower', 'Panorama Tower', ['Panorama Tower'], { x: 330, z: 1050 }],
  ['riverwalk', 'Miami Riverwalk', 'Riverwalk', ['Miami Riverwalk'], { x: 200, z: 380 }],
  ['courthouse', 'Dade County Courthouse', 'Courthouse', ['Dade County Courthouse'], { x: -250, z: -40 }]
];
const NYC_LANDMARKS = MIAMI_LANDMARKS.map(([id, name, short, osm, fallback]) => {
  const s = site(osm, fallback);
  return { id, name, short, x: s.x, z: s.z, district: DISTRICT_NAMES[districtAt(s.x, s.z)] };
});
const lmById = (id) => NYC_LANDMARKS.find((l) => l.id === id);

// Street-level arrivals: the nearest road centreline to a landmark, facing it. Heading 0 faces south (+z), PI north.
function arrivalNear(x, z, back = 40) {
  const near = nearestRoads(x, z, 260).filter((r) => !/I-95|I-395|Interstate/.test(r.road.name));
  let px = x, pz = z;
  if (near.length) {
    const r = near[0].road;
    let best = null;
    for (let i = 0; i + 1 < r.pts.length; i++) {
      const a = r.pts[i], b = r.pts[i + 1];
      const dx = b.x - a.x, dz = b.z - a.z;
      const t = Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz || 1e-9)));
      const qx = a.x + dx * t, qz = a.z + dz * t;
      const d = Math.hypot(qx - x, qz - z);
      if (!best || d < best.d) best = { d, x: qx, z: qz };
    }
    if (best && best.d > back) {
      px = best.x;
      pz = best.z;
    } else if (best) {
      px = best.x;
      pz = best.z;
    }
  }
  return { x: px, z: pz, heading: Math.atan2(x - px, z - pz) };
}
const TELEPORT_LOCATIONS = Object.fromEntries(NYC_LANDMARKS.map((l) => [l.id, arrivalNear(l.x, l.z)]));
// Spawn: Biscayne Blvd at Bayfront Park, looking north up the boulevard toward the Freedom Tower
TELEPORT_LOCATIONS.spawn = arrivalNear(lmById('bayfront').x - 160, lmById('bayfront').z - 200);

/** Superblock bounds (the New York landmark builder's API; unused in Miami) */
function getBlockBounds() {
  return { minX: 0, maxX: 0, minZ: 0, maxZ: 0, cx: 0, cz: 0, width: 0, depth: 0, sidewalkMinX: 0, sidewalkMaxX: 0, sidewalkMinZ: 0, sidewalkMaxZ: 0 };
}

/** Street / landmark name at any world (x, z): the nearest roads of the OSM centreline */
function getLocationLabel(x, z) {
  for (const lm of NYC_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const near = nearestRoads(x, z, 120);
      return near.length ? `${lm.name} · ${near[0].road.name}` : lm.name;
    }
  }
  if (isWaterAt(x, z)) {
    if (onBridgeDeck(x, z, 6)) return nearestRoads(x, z, 40)[0]?.road.name || 'Bridge';
    return z > -100 && z < 700 && x < 700 ? 'Miami River' : 'Biscayne Bay';
  }
  const near = nearestRoads(x, z, 160);
  const ns = near.find((r) => !r.horizontal);
  const ew = near.find((r) => r.horizontal);
  if (ns && ew) return `${ns.road.name} & ${ew.road.name}`;
  if (near.length) return `${near[0].road.name} · ${DISTRICT_NAMES[districtAt(x, z)]}`;
  return DISTRICT_NAMES[districtAt(x, z)] || CITY_NAME;
}

/** The New York original's old compressed frame -> world (identity here: nothing in Miami was authored in it) */
const fromOldFrame = (x, z) => ({ x, z });

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// north-south ("avenue") traffic green until avenueAmber, amber until avenueRed; east-west green from avenueRed until
// streetAmber, amber until the end of the cycle. Pedestrians step off on the WALK, the first `walk` seconds.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

